    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    marked_rows = {}
    marked_cols = {}
    for r, c in markers:
        marked_rows.setdefault(r, []).append(c)
        marked_cols.setdefault(c, []).append(r)

    line = set()
    for r, cols in marked_rows.items():
        if len(cols) >= 2:
            for c in range(min(cols), max(cols) + 1):
                line.add((r, c))
    for c, rows in marked_cols.items():
        if len(rows) >= 2:
            for r in range(min(rows), max(rows) + 1):
                line.add((r, c))

    # A line that crosses any part of a 2-component converts the whole object.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            comp = []
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                comp.append((y, x))
